```python
"""Data-bearing local message gate; NOT an OS sandbox or probabilistic auditor.

L: lifecycle/shape only (deliberately lacks task semantics).
V: exact task-content validation of a staged proposer report at COMMIT.
C: typed server renderer, no proposer report parameter.
All instances share this storage/lifecycle implementation; they are not
independently engineered security products. Only local SQL effects exist.
"""
import json
import sqlite3
from copy import deepcopy
from threading import RLock


def canonical(value):
    return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False)


def decode(raw):
    """Reject duplicate JSON keys at the transport boundary rather than overwrite."""
    if not isinstance(raw,str) or len(raw.encode('utf-8'))>65536:
        raise ValueError('MESSAGE_SIZE')
    def pairs(items):
        out={}
        for k,v in items:
            if k in out: raise ValueError('DUPLICATE_KEY')
            out[k]=v
        return out
    def nonfinite(_): raise ValueError('NONFINITE_JSON')
    return json.loads(raw,object_pairs_hook=pairs,parse_constant=nonfinite)


def row_shape(report):
    """Common generic shape check, deliberately not a task-semantic validator."""
    return (type(report) is dict and type(report.get('task')) is str
            and type(report.get('destination')) is str
            and type(report.get('rows')) is list and len(report['rows'])<=100
            and type(report.get('count')) is int and report['count']>=0
            and all(type(r) is dict and all(type(r.get(k)) is str
                        for k in ('id','title','status')) for r in report['rows']))


def proposed_ok(task, records, report):
    """V validator: check fields, sets and values, without calling C renderer."""
    if not row_shape(report) or set(report)!={'task','destination','rows','count'}:
        return False
    if report['task']!=task['id'] or report['destination']!=task['destination']:
        return False
    expected={}
    for row in records:
        if (row['project']==task['project'] and row['release']==task['release']
            and row['approved'] is True and row['status'] in task['statuses']):
            expected[row['id']]=(row['title'],row['status'])
    seen=set()
    for row in report['rows']:
        if set(row)!={'id','title','status'} or row['id'] in seen: return False
        if expected.get(row['id'])!=(row['title'],row['status']): return False
        seen.add(row['id'])
    return seen==set(expected) and report['count']==len(expected)


def render(task, records):
    """C's typed implementation constructs allowed content rather than trusting it."""
    rows=[{'id':r['id'],'title':r['title'],'status':r['status']} for r in records
          if r['project']==task['project'] and r['release']==task['release']
          and r['approved'] is True and r['status'] in task['statuses']]
    rows.sort(key=lambda r:r['id'])
    return {'task':task['id'],'destination':task['destination'],'count':len(rows),'rows':rows}


class ExportGate:
    def __init__(self, mode, fixture=None, path=':memory:'):
        if mode not in ('L','V','C'): raise ValueError('MODE')
        self.mode=mode; self.lock=RLock()
        self.db=sqlite3.connect(path,isolation_level=None,check_same_thread=False)
        self.db.executescript('''
        CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY, body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS tickets(id INTEGER PRIMARY KEY AUTOINCREMENT, body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS effects(id INTEGER PRIMARY KEY AUTOINCREMENT,
          ticket INTEGER UNIQUE NOT NULL, task TEXT NOT NULL, owner TEXT NOT NULL,
          revision INTEGER NOT NULL, report TEXT NOT NULL, UNIQUE(task,owner));
        CREATE TABLE IF NOT EXISTS events(seq INTEGER PRIMARY KEY AUTOINCREMENT, body TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS snapshots(revision INTEGER PRIMARY KEY, body TEXT NOT NULL);
        ''')
        with self.lock:
            self.db.execute('BEGIN IMMEDIATE')
            try:
                state=self.db.execute('SELECT body FROM state WHERE id=1').fetchone()
                if state is None:
                    if fixture is None: raise ValueError('INITIAL_FIXTURE_REQUIRED')
                    s=deepcopy(fixture)
                    self._validate_fixture(s)
                    s.update(mode=mode, revision=0, spent=0, stopped=False)
                    self._save(s); self._snapshot(s)
                elif json.loads(state[0])['mode']!=mode:
                    raise ValueError('REOPEN_MODE_MISMATCH')
                self.db.execute('COMMIT')
            except BaseException:
                self.db.execute('ROLLBACK'); self.db.close(); raise

    @staticmethod
    def _validate_fixture(f):
        if type(f.get('cap')) is not int or not 0<=f['cap']<=1000: raise ValueError('CAP')
        for key in ('tasks','records'):
            if type(f.get(key)) is not list: raise ValueError('FIXTURE')
            ids=[r['id'] for r in f[key]]
            if len(ids)!=len(set(ids)): raise ValueError('DUPLICATE_SOURCE_ID')
        for r in f['records']:
            if type(r['approved']) is not bool: raise ValueError('APPROVAL_TYPE')
            if any(type(r[k]) is not str for k in ('id','project','release','status','title')):
                raise ValueError('RECORD_TYPE')
        for t in f['tasks']:
            if type(t['active']) is not bool or type(t['statuses']) is not list:
                raise ValueError('TASK_TYPE')
            if any(type(t[k]) is not str for k in ('id','owner','project','release','destination')):
                raise ValueError('TASK_TYPE')
            if any(type(x) is not str for x in t['statuses']): raise ValueError('STATUS_TYPE')

    def _load(self):
        return json.loads(self.db.execute('SELECT body FROM state WHERE id=1').fetchone()[0])
    def _save(self,s):
        self.db.execute('INSERT OR REPLACE INTO state VALUES(1,?)',(canonical(s),))
    def _snapshot(self,s):
        self.db.execute('INSERT INTO snapshots VALUES(?,?)',
                        (s['revision'],canonical({'tasks':s['tasks'],'records':s['records']})))
    def _ticket(self,ticket,t):
        self.db.execute('UPDATE tickets SET body=? WHERE id=?',(canonical(t),ticket))
    def _event(self,data):
        self.db.execute('INSERT INTO events(body) VALUES(?)',(canonical(data),))
    @staticmethod
    def deny(reason): return {'status':'REFUSED','reason':reason}

    def request_raw(self, owner, raw):
        try: message=decode(raw)
        except (ValueError,TypeError,RecursionError) as exc:
            return self.deny('TRANSPORT_'+str(exc))
        return self.request(owner,message)

    def request(self, owner, message):
        """owner is supplied by the trusted caller adapter, not a message field."""
        with self.lock:
            self.db.execute('BEGIN IMMEDIATE')
            try:
                state=self._load()
                out=self._apply(state,owner,message)
                self._save(state)
                self._event({'kind':'request','owner':owner,'request':message,
                             'response':out,'revision':state['revision'],'spent':state['spent']})
                self.db.execute('COMMIT')
                return out
            except BaseException:
                self.db.execute('ROLLBACK'); raise


